# Original derivation unit: derive_a1.py
"""A1 WKB layers at symbolic spin, derived before comparison data are read.

Q=K^2 Lambda+X f+Y g+v. Expand the universal Riccati solution by derivative
order, reduce by exact total derivatives, then extract the large-K power.
This file does not import charge tables or previously computed A1 values.
"""
from fractions import Fraction as derive_a1__Q
from pathlib import Path as derive_a1__Path
import json as derive_a1__json, math as derive_a1__math, time as derive_a1__time
import sympy as derive_a1__S
from flint import fmpq as derive_a1__fmpq, fmpq_mpoly_ctx as derive_a1__fmpq_mpoly_ctx
derive_a1__ZERO = (0,) * 6

def derive_a1__add(p, r, c=derive_a1__Q(1)):
    p = dict(p)
    for key, v in r.items():
        p[key] = p.get(key, derive_a1__Q(0)) + c * v
    return {key: v for key, v in p.items() if v}

def derive_a1__mul(p, r):
    ans = {}
    for (ex, m), v in p.items():
        for (ey, derive_a1__n), z in r.items():
            key = (ex + ey, tuple((derive_a1__a + derive_a1__b for derive_a1__a, derive_a1__b in zip(m, derive_a1__n))))
            ans[key] = ans.get(key, derive_a1__Q(0)) + v * z
    return {key: v for key, v in ans.items() if v}

def derive_a1__derivative(p):
    ans = {}
    for (ex, m), v in p.items():
        mm = list(m)
        mm[0] += 1
        key = (ex - 2, tuple(mm))
        ans[key] = ans.get(key, derive_a1__Q(0)) + derive_a1__Q(ex, 2) * v
        for r in range(5):
            if not m[r]:
                continue
            mm = list(m)
            mm[r] -= 1
            mm[r + 1] += 1
            key = (ex, tuple(mm))
            ans[key] = ans.get(key, derive_a1__Q(0)) + m[r] * v
    return {key: v for key, v in ans.items() if v}

def derive_a1__partitions(derive_a1__n, lo=1):
    if not derive_a1__n:
        yield ()
        return
    for j in range(lo, derive_a1__n + 1):
        for rest in derive_a1__partitions(derive_a1__n - j, j):
            yield ((j,) + rest)

def derive_a1__counts(p):
    return tuple((p.count(j) for j in range(1, 7)))

def derive_a1__universal():
    ric = [{(1, derive_a1__ZERO): derive_a1__Q(1)}]
    for j in range(1, 7):
        acc = derive_a1__derivative(ric[-1])
        for i in range(1, j):
            acc = derive_a1__add(acc, derive_a1__mul(ric[i], ric[j - i]))
        ric.append({(ex - 1, m): -v / 2 for (ex, m), v in acc.items()})
    bases = {1: [(1, 1)], 2: [(2, 2), (1, 1, 1, 1)], 3: [(3, 3), (2, 2, 2), (1, 1, 2, 2), (1, 1, 1, 1, 1, 1)]}
    reduced = {0: {(1, derive_a1__ZERO): derive_a1__Q(1)}}
    primitives = {}
    for g in (1, 2, 3):
        mons = [derive_a1__counts(p) for p in derive_a1__partitions(2 * g)]
        keys = [(1 - 2 * g - 2 * sum(m), m) for m in mons]
        sources = [{(1 - 2 * g - 2 * sum(m), m): derive_a1__Q(1)} for m in map(derive_a1__counts, derive_a1__partitions(2 * g - 1))]
        basis = [{(1 - 2 * g - 2 * len(p), derive_a1__counts(p)): derive_a1__Q(1)} for p in bases[g]]
        cols = [derive_a1__derivative(p) for p in sources] + basis
        A = derive_a1__S.Matrix([[derive_a1__S.Rational(col.get(key, 0)) for col in cols] for key in keys])
        rhs = derive_a1__S.Matrix([derive_a1__S.Rational(ric[2 * g].get(key, 0)) for key in keys])
        sol = list(A.inv() * rhs)
        primitive = {}
        red = {}
        for i, v in enumerate(sol):
            value = derive_a1__Q(int(v.p), int(v.q))
            if i < len(sources):
                primitive = derive_a1__add(primitive, sources[i], value)
            else:
                red = derive_a1__add(red, basis[i - len(sources)], value)
        if derive_a1__add(derive_a1__add(ric[2 * g], red, -1), derive_a1__derivative(primitive), -1):
            raise ArithmeticError('IBP residual')
        primitives[g] = primitive
        reduced[g] = red
    return (ric, reduced, primitives)
derive_a1__CTX = derive_a1__fmpq_mpoly_ctx.get(('w', 'k', 'a', 'n', 'e', 'b'))
derive_a1__w, derive_a1__k, derive_a1__a, derive_a1__n, derive_a1__e, derive_a1__b = derive_a1__CTX.gens()
derive_a1__Z = derive_a1__CTX.constant(0)
derive_a1__f = lambda x: derive_a1__fmpq(str(x))

def derive_a1__fall(x, m):
    r = derive_a1__CTX.constant(1)
    for j in range(m):
        r *= x - j
    return r

def derive_a1__rise(x, m):
    r = derive_a1__CTX.constant(1)
    for j in range(m):
        r *= x + j
    return r

def derive_a1__D(p):
    return derive_a1__w * (1 - derive_a1__w) * p.derivative(0)

def derive_a1__expand_q_derivatives(m, L, FX, GY, V):
    ans = {(0, 0, 0, 0): derive_a1__CTX.constant(1)}
    for r, count in enumerate(m, 1):
        for _ in range(count):
            new = {}
            for tags, p in ans.items():
                for kind, v in enumerate((L[r], FX[r], GY[r], V[r])):
                    tag = list(tags)
                    tag[kind] += 1
                    tag = tuple(tag)
                    new[tag] = new.get(tag, derive_a1__Z) + p * v
            ans = new
    return ans

def derive_a1__derive(out):
    start = derive_a1__time.monotonic()
    ric, reduced, primitives = derive_a1__universal()

    def encoded(p):
        return [{'Q0_exponent_twice': ex, 'jet_powers': m, 'coefficient': str(v)} for (ex, m), v in p.items()]
    universal_record = {'riccati': {j: encoded(p) for j, p in enumerate(ric)}, 'reduced': {j: encoded(p) for j, p in reduced.items()}, 'primitives': {j: encoded(p) for j, p in primitives.items()}, 'IBP_residuals_zero': True}
    (out / 'universal_wkb.json').write_text(derive_a1__json.dumps(universal_record, indent=2) + '\n')
    print('EXACT reduced WKB densities:', {g: encoded(v) for g, v in reduced.items()}, flush=True)
    L = [derive_a1__CTX.constant(1)]
    FX = [derive_a1__CTX.constant(1)]
    GY = [derive_a1__CTX.constant(1)]
    V = [(1 - derive_a1__w) * (derive_a1__b * derive_a1__w - derive_a1__e / 24)]
    for j in range(6):
        L.append(derive_a1__D(L[-1]) + (-derive_a1__e + derive_a1__n * derive_a1__w) * L[-1])
        FX.append(derive_a1__D(FX[-1]) + (1 - derive_a1__w) * FX[-1])
        GY.append(derive_a1__D(GY[-1]) + (1 - 2 * derive_a1__w) * GY[-1])
        V.append(derive_a1__D(V[-1]))
    expansions = {}
    for g, p in reduced.items():
        for (ex, m), v in p.items():
            expansions[g, m] = derive_a1__expand_q_derivatives(m, L, FX, GY, V)
    A = (derive_a1__k - derive_a1__f('1/2')) * derive_a1__e + derive_a1__k
    B = (derive_a1__k - derive_a1__f('1/2')) * (derive_a1__n - derive_a1__e) + derive_a1__k - derive_a1__a
    AB = A + B
    for d in (0, 1, 2, 3):
        H = derive_a1__Z
        for g, p in reduced.items():
            if g > d:
                continue
            for (ex, m), v in p.items():
                M = sum(m)
                den = derive_a1__Q(1)
                for j in range(g + M):
                    den *= derive_a1__Q(1, 2) - j
                for (mL, mX, mY, mV), poly in expansions[g, m].items():
                    r = d - g - mV
                    if r < 0:
                        continue
                    weight = derive_a1__fall(derive_a1__a, mX) * derive_a1__fall(derive_a1__k - derive_a1__a - d, mY) * derive_a1__fall(derive_a1__f('1/2') - derive_a1__k, mL) * derive_a1__f(v / den / derive_a1__Q(derive_a1__math.factorial(r)))
                    H += weight * poly * V[0] ** r
        coeff = {j: derive_a1__Z for j in range(2 * d + 1)}
        for mon, v in H.to_dict().items():
            if mon[0] > 2 * d:
                raise ArithmeticError('finite degree bound failed')
            key = (0,) + mon[1:]
            coeff[mon[0]] += derive_a1__CTX.from_dict({key: v})
        N = derive_a1__Z
        for j, p in coeff.items():
            N += p * derive_a1__rise(A - d, j) * derive_a1__rise(AB - 2 * d + j, 2 * d - j)
        den = derive_a1__rise(A - d, d) * derive_a1__rise(B - d, d) * ((derive_a1__n + 2) / 2) ** d
        gcd = N.gcd(den)
        num = N // gcd
        den = den // gcd
        record = {'layer_drop': d, 'normalization': 'coefficient / top-symbol c_a', 'common_factor': 'falling(k-a,d)', 'numerator': str(num), 'denominator': str(den), 'H_coefficients': {j: str(v) for j, v in coeff.items()}, 'variables': ['w', 'k', 'a', 'n', 'e', 'b'], 'b': '1/4+d2', 'term_count': len(num.to_dict())}
        (out / f'universal_layer{d}.json').write_text(derive_a1__json.dumps(record, indent=2) + '\n')
        print('EXACT layer', d, 'numerator terms', record['term_count'], 'elapsed', round(derive_a1__time.monotonic() - start, 2), flush=True)

# Original derivation unit: project_a1.py
"""Specialize the derived universal A1 layers and subtract the Ward laws."""
from pathlib import Path as project_a1__Path
import json as project_a1__json, time as project_a1__time
from flint import fmpq as project_a1__fmpq, fmpq_mpoly as project_a1__fmpq_mpoly, fmpq_mpoly_ctx as project_a1__fmpq_mpoly_ctx
import sympy as project_a1__S
project_a1__C = project_a1__fmpq_mpoly_ctx.get(('k', 'a', 't'))
project_a1__k, project_a1__a, project_a1__t = project_a1__C.gens()
project_a1__Z = project_a1__C.constant(0)
project_a1__F = project_a1__fmpq

def project_a1__parse(s, ctx=project_a1__C):
    return project_a1__fmpq_mpoly(s.replace('**', '^'), ctx)

def project_a1__clean(num, den):
    g = num.gcd(den)
    num = num // g
    den = den // g
    if not den:
        raise ArithmeticError('zero denominator')
    return (num, den)

def project_a1__branch_data(sol):
    if sol == 1:
        D = (project_a1__t + 3) * (project_a1__t + 1)
        nn = -(project_a1__t + 7) * (project_a1__t + 1)
        ee = -4 * (project_a1__t + 1)
        bb = D / 4 - 1
    elif sol == 2:
        D = (project_a1__t + 5) * (project_a1__t + 1)
        nn = 2 * (project_a1__t - 7) * (project_a1__t + 1)
        ee = -8 * (project_a1__t + 1)
        bb = D / 4 - 4
    else:
        D = (project_a1__t - 5) * (project_a1__t * project_a1__t - 1)
        nn = -(project_a1__t - 7) * (project_a1__t * project_a1__t - 1)
        ee = 4 * (project_a1__t * project_a1__t - 1)
        bb = D / 4 - (project_a1__t - 3)
    return (D, nn, ee, bb)

def project_a1__specialize(poly, sol):
    vals = poly.to_dict()
    L = max((m[3] + m[4] + m[5] for m in vals), default=0)
    D, nn, ee, bb = project_a1__branch_data(sol)
    powers = {}
    for j, v in enumerate((nn, ee, bb, D)):
        powers[j] = [project_a1__C.constant(1)]
        for i in range(L):
            powers[j].append(powers[j][-1] * v)
    cache = {}
    out = {}
    for (wexp, ke, ae, ne, ee_, be), v in vals.items():
        if wexp:
            raise ArithmeticError('unintegrated spatial variable')
        tag = (ne, ee_, be)
        if tag not in cache:
            cache[tag] = (powers[0][ne] * powers[1][ee_] * powers[2][be] * powers[3][L - ne - ee_ - be]).to_dict()
        for (kk, aa, te), vv in cache[tag].items():
            key = (ke + kk, ae + aa, te)
            out[key] = out.get(key, project_a1__F(0)) + v * vv
    return (project_a1__C.from_dict(out), powers[3][L])

def project_a1__pair(expr):
    num, den = project_a1__S.fraction(project_a1__S.sympify(expr))
    return (project_a1__parse(str(num)), project_a1__parse(str(den)))

def project_a1__encode(project_a1__pair):
    return {'numerator': str(project_a1__pair[0]), 'denominator': str(project_a1__pair[1])}

def project_a1__run(out, source):
    start = project_a1__time.monotonic()
    anchors = []
    for sol in (1, 2, 3):
        for d in (0, 1, 2, 3):
            un = project_a1__json.loads((out / f'universal_layer{d}.json').read_text())
            N, D = (project_a1__parse(un['numerator'], derive_a1__CTX), project_a1__parse(un['denominator'], derive_a1__CTX))
            sn, sd = project_a1__specialize(N, sol)
            dn, dd = project_a1__specialize(D, sol)
            numerator = sn * dd
            denominator = sd * dn
            for j in range(d):
                numerator *= project_a1__k - project_a1__a - j
            A = project_a1__clean(numerator, denominator)
            record = {'solution': sol, 'drop': d, 'normalization': 'coefficient of X^a Y^(k-d-a) divided by the top-symbol coefficient c_a', 'A1': project_a1__encode(A)}
            if d >= 2:
                data = project_a1__json.loads((source / f'ward_layer{d}_sol{sol}.json').read_text())
                W = project_a1__pair(data['projection_over_c_a'])
                Delta = project_a1__clean(W[0] * A[1] - A[0] * W[1], W[1] * A[1])
                record['Ward'] = project_a1__encode(W)
                record['Delta_A1'] = project_a1__encode(Delta)
                if sol in (1, 2):
                    tv = project_a1__F(-1, 3) if sol == 1 else project_a1__F(1, 3)
                    AK = project_a1__fmpq_mpoly_ctx.get(('k', 'a'))
                    kk, aa = AK.gens()
                    nn = Delta[0].compose(kk, aa, AK.constant(tv))
                    dd_ = Delta[1].compose(kk, aa, AK.constant(tv))
                    good = not nn and bool(dd_)
                    if not good:
                        raise ArithmeticError(f'exact-point identity failed: {(sol, d)}')
                    anchors.append({'sol': sol, 'drop': d, 't': str(tv), 'symbolic_k_a_zero': True})
                else:
                    nd, dd_ = (int(Delta[0].degrees()[2]), int(Delta[1].degrees()[2]))
                    good = nd < dd_ or not Delta[0]
                    if not good:
                        raise ArithmeticError(f'paperclip identity failed: {(sol, d, nd, dd_)}')
                    anchors.append({'sol': sol, 'drop': d, 't': 'infinity', 'numerator_degree_t': nd, 'denominator_degree_t': dd_, 'symbolic_k_a_zero': True})
            (out / f'a1_sol{sol}_layer{d}.json').write_text(project_a1__json.dumps(record, indent=2) + '\n')
            print('EXACT specialized sol', sol, 'layer', d, 'A1 monomials', len(A[0].to_dict()), len(A[1].to_dict()), 'elapsed', round(project_a1__time.monotonic() - start, 2), flush=True)
    (out / 'exact_point_identities.json').write_text(project_a1__json.dumps({'status': 'EXACT', 'identities': anchors}, indent=2) + '\n')

# Original derivation unit: check_a1.py
"""Untouched A1 hold-outs and singular-normalization Laurent coefficients."""
from pathlib import Path as check_a1__Path
import json as check_a1__json, math as check_a1__math
import sympy as check_a1__S
from functools import lru_cache as check_a1__lru_cache
from flint import fmpq as check_a1__F, fmpq_mpoly_ctx as check_a1__fmpq_mpoly_ctx, fmpq_mpoly as check_a1__fmpq_mpoly, fmpq_poly as check_a1__fmpq_poly
check_a1__T = check_a1__fmpq_mpoly_ctx.get(('t',))
check_a1__t, = check_a1__T.gens()

def check_a1__clean(n, d):
    g = n.gcd(d)
    if not d:
        raise ArithmeticError('zero denominator')
    return (n // g, d // g)

@check_a1__lru_cache(None)
def check_a1__top(sol, K, A):
    if sol == 1:
        D = check_a1__t + 3
        b = check_a1__t - 1
        c = D
    elif sol == 2:
        D = check_a1__t + 5
        b = 4 * (check_a1__t - 1)
        c = -2 * (check_a1__t - 3)
    else:
        D = check_a1__t - 5
        b = c = check_a1__t - 3
    n = check_a1__T.constant(check_a1__math.comb(K, A)) * b ** (K - A)
    d = c ** (K - A)
    h = check_a1__F(2 * K - 1, 2)
    for j in range(A):
        n *= -b * h + j * D
    for j in range(K - A):
        n *= -c * h + j * D
    for j in range(K):
        d *= -b * h + j * D
    return check_a1__clean(n, d)

@check_a1__lru_cache(None)
def check_a1__layer(path, sol, drop, field):
    data = check_a1__json.loads((check_a1__Path(path) / f'a1_sol{sol}_layer{drop}.json').read_text())[field]
    return (project_a1__parse(data['numerator']), project_a1__parse(data['denominator']))

def check_a1__coefficient(path, sol, K, A, drop, field='A1'):
    n, d = check_a1__layer(str(path), sol, drop, field)
    n = n.compose(check_a1__T.constant(K), check_a1__T.constant(A), check_a1__t)
    d = d.compose(check_a1__T.constant(K), check_a1__T.constant(A), check_a1__t)
    tn, td = check_a1__top(sol, K, A)
    return check_a1__clean(n * tn, d * td)

def check_a1__univariate(p):
    out = check_a1__fmpq_poly([])
    for (i,), v in p.to_dict().items():
        out[i] = v
    return out

def check_a1__value(pair, tv):
    n, d = map(check_a1__univariate, pair)
    return n(tv) / d(tv)

def check_a1__laurent(pair, tv):
    n, d = map(check_a1__univariate, pair)
    shift = check_a1__fmpq_poly([tv, 1])
    n = n(shift)
    d = d(shift)
    vn = next((i for i, v in enumerate(n) if v)) if n else 1000
    vd = next((i for i, v in enumerate(d) if v))
    if vn < vd - 1:
        raise ArithmeticError('unexpected higher pole')
    if vn >= vd:
        return (check_a1__F(0), n[vd] / d[vd])
    residue = n[vd - 1] / d[vd]
    finite = n[vd] / d[vd] - n[vd - 1] * d[vd + 1] / d[vd] ** 2
    return (residue, finite)

def check_a1__run(path):
    path = check_a1__Path(path)
    old = check_a1__json.loads((path / 'source/class1_results.json').read_text())
    checks = []
    singular = []
    for row in old['rows']:
        if 'coefficients' not in row:
            continue
        sol, K, tv = (row['sol'], (row['spin'] + 1) // 2, check_a1__F(row['t']))
        if not isinstance(row['base_beta_denominator_zero'], dict):
            for c in row['coefficients']:
                A, B = (c['X'], c['Y'])
                drop = K - A - B
                if drop not in (2, 3):
                    continue
                v = check_a1__value(check_a1__coefficient(path, sol, K, A, drop), tv)
                w = check_a1__value(check_a1__coefficient(path, sol, K, A, drop, 'Ward'), tv)
                if v != check_a1__F(c['A1']) or w != check_a1__F(c['charge']):
                    raise ArithmeticError(f'hold-out mismatch {(sol, K, tv, A, B, v, w)}')
                checks.append({'sol': sol, 'spin': 2 * K - 1, 't': str(tv), 'X': A, 'Y': B, 'A1': str(v), 'Ward': str(w), 'equal': True})
        else:
            singular_data = row['base_beta_denominator_zero']
            expected = singular_data.get('normalized_pole_residues')
            if expected is None:
                if (sol, K, tv) != (2, 5, check_a1__F(4)):
                    raise ArithmeticError('unaccounted singular row')
                z = check_a1__S.symbols('t')
                s = 2 * K - 1
                nn = 2 * (z - 7) / (z + 5)
                ee = -8 / (z + 5)
                cc = -2 * (z - 3) / (z + 5)
                raw = check_a1__S.cancel(check_a1__S.binomial(check_a1__S.Rational(1, 2), K) * (-cc / 2) ** K * check_a1__S.rf(s * ee / 2, K) / check_a1__S.rf(s * nn / 2, K))
                slope = check_a1__S.diff(s * nn / 2, z).subs(z, 4) * raw.subs(z, 4)
                expected = {key: str(check_a1__S.Rational(v) / slope) for key, v in singular_data['common_factor_polynomial'].items()}
            for drop in (2, 3):
                for A in range(K - drop + 1):
                    B = K - drop - A
                    res, fp = check_a1__laurent(check_a1__coefficient(path, sol, K, A, drop), tv)
                    if res != check_a1__F(expected.get(str((A, B)), '0')):
                        raise ArithmeticError('residue hold-out failed')
                    w = check_a1__value(check_a1__coefficient(path, sol, K, A, drop, 'Ward'), tv)
                    singular.append({'sol': sol, 'spin': 2 * K - 1, 't': str(tv), 'X': A, 'Y': B, 'residue': str(res), 'finite_part': str(fp), 'Ward': str(w), 'finite_part_minus_Ward': str(fp - w), 'residue_holdout': True})
    if len(checks) != 243 or len(singular) != 12:
        raise ArithmeticError(f'inventory {(len(checks), len(singular))}')
    (path / 'a1_holdouts.json').write_text(check_a1__json.dumps({'status': 'EXACT', 'fit': 'none', 'matches': len(checks), 'rows': checks, 'singular': singular}, indent=2) + '\n')
    print('EXACT 243 A1 and 243 Ward hold-out comparisons match; 12 singular-layer residues match; fixed-t Laurent finite parts saved.', flush=True)
    for row in singular:
        print(row, flush=True)

# Original derivation unit: upper_layers_check.py
"""Symbolic check that A1's sub-top layer is the single Wick contraction."""
from pathlib import Path as upper_layers_check__Path
import json as upper_layers_check__json
import sympy as upper_layers_check__S
from flint import fmpq as upper_layers_check__F, fmpq_mpoly_ctx as upper_layers_check__fmpq_mpoly_ctx

def upper_layers_check__run(out):
    k, a, t = upper_layers_check__S.symbols('k a t')
    N = (t * t - 25) / (t * t - 1)
    records = []
    for sol in (1, 2, 3):
        cx, a2 = {1: (upper_layers_check__S.Integer(1), (t - 1) / (t + 3)), 2: (-2 * (t - 3) / (t + 5), 4 * (t - 1) / (t + 5)), 3: ((t - 3) / (t - 5), (t - 3) / (t - 5))}[sol]
        ratio = (k - a) / (a + 1) * (a - a2 * (k - upper_layers_check__S.Rational(1, 2))) / (k - a - 1 - cx * (k - upper_layers_check__S.Rational(1, 2))) * (cx / a2)
        wick = upper_layers_check__S.cancel(((a + 1) * (2 * a + 1) * ratio + (k - a) * (2 * (k - a) + N - 2)) / 12)
        nn, dd = upper_layers_check__S.fraction(wick)
        nn, dd = (project_a1__parse(str(nn)), project_a1__parse(str(dd)))
        p = upper_layers_check__json.loads((out / f'a1_sol{sol}_layer1.json').read_text())['A1']
        an, ad = (project_a1__parse(p['numerator']), project_a1__parse(p['denominator']))
        residual = nn * ad - an * dd
        if residual:
            raise ArithmeticError(f'symbolic sub-top mismatch {sol}')
        records.append({'solution': sol, 'Ward_single_contraction_over_c_a': str(wick), 'A1_minus_Ward_zero': True})
    (out / 'upper_layers_check.json').write_text(upper_layers_check__json.dumps({'status': 'EXACT', 'method': 'one cylinder Wick contraction of the top density; no charge-table input', 'identity': 'subtop/c_a = [(a+1)(2a+1)c_(a+1)/c_a + (k-a)(2(k-a)+N-2)]/12', 'rows': records}, indent=2) + '\n')
    print('EXACT A1 sub-top equals single Wick contraction identically in k,a,t on all three components.', flush=True)
    KA = upper_layers_check__fmpq_mpoly_ctx.get(('k', 'a'))
    kk, aa = KA.gens()
    transfers = []
    for drop in (2, 3):
        pairs = []
        for sol, tv in ((1, upper_layers_check__F(-1, 3)), (2, upper_layers_check__F(1, 3))):
            doc = upper_layers_check__json.loads((out / f'a1_sol{sol}_layer{drop}.json').read_text())['Delta_A1']
            pn, pd = (project_a1__parse(doc['numerator']), project_a1__parse(doc['denominator']))
            pairs.append((pn.derivative(2).compose(kk, aa, KA.constant(tv)), pd.compose(kk, aa, KA.constant(tv))))
        n1, d1 = pairs[0]
        n2, d2 = pairs[1]
        if 2 * n2 * d1 - n1 * d2:
            raise ArithmeticError('exact-point tangent transfer failed')
        transfers.append({'drop': drop, 'Sol2_tangent_is_half_Sol1': True})
    (out / 'two_anchor_tangents.json').write_text(upper_layers_check__json.dumps({'status': 'EXACT', 'identities': transfers, 'same_A1_base': True, 'relation_target_Sol1': '1', 'relation_target_Sol2': '1/2'}, indent=2) + '\n')
    print('EXACT both lower-layer tangents on Sol2 are half Sol1 identically in k,a; same obstruction transfers.', flush=True)

# Original derivation unit: moment_problem.py
"""Exact seven-function moment operator; no spatial-shape ansatz or fit.

Source classes are delta Q=kappa^-2 Lambda^-1 X^r Y^s U(w), r+s<=2,
and delta Q=kappa^-4 Lambda^-2 H(w).  The Lambda factors absorb arbitrary
shapes.  At the exact point Lambda=w^(3/2)(1-w), all adjoint kernels
at spins congruent modulo four reduce to polynomial identities.
"""
from pathlib import Path as moment_problem__Path
import json as moment_problem__json, math as moment_problem__math, time as moment_problem__time
from fractions import Fraction as moment_problem__Q
from functools import lru_cache as moment_problem__lru_cache
from flint import fmpq as moment_problem__F, fmpq_mpoly_ctx as moment_problem__fmpq_mpoly_ctx, fmpq_mat as moment_problem__fmpq_mat, fmpq_poly as moment_problem__fmpq_poly
moment_problem__C = moment_problem__fmpq_mpoly_ctx.get(('w', 'X', 'Y'))
moment_problem__w, moment_problem__X, moment_problem__Y = moment_problem__C.gens()
moment_problem__Z = moment_problem__C.constant(0)
moment_problem__KINDS = {'U': (0, 0), 'XU': (1, 0), 'YU': (0, 1), 'XX': (2, 0), 'XY': (1, 1), 'YY': (0, 2), 'U4': None}

def moment_problem__D(p):
    return moment_problem__w * (1 - moment_problem__w) * p.derivative(0)

def moment_problem__binom(x, n):
    r = moment_problem__F(1)
    for i in range(n):
        r *= x - i
        r /= i + 1
    return r

def moment_problem__encode(p):
    return {','.join(map(str, m)): str(v) for m, v in p.to_dict().items()}

def moment_problem__decode(p):
    return moment_problem__C.from_dict({tuple(map(int, m.split(','))): moment_problem__F(v) for m, v in p.items()})

def moment_problem__euler(p):
    ans = {}
    for (ex, m), v in p.items():
        ans = derive_a1__add(ans, {(ex - 2, m): v * moment_problem__Q(ex, 2)})
        for r in range(1, 7):
            if not m[r - 1]:
                continue
            mm = list(m)
            mm[r - 1] -= 1
            q = {(ex, tuple(mm)): v * m[r - 1]}
            for j in range(r):
                q = {key: -val for key, val in derive_a1__derivative(q).items()}
            ans = derive_a1__add(ans, q)
    return ans

def moment_problem__grade(p, min_degree, max_degree):
    return moment_problem__C.from_dict({m: v for m, v in p.to_dict().items() if min_degree <= m[1] + m[2] <= max_degree})

def moment_problem__spatial_coefficient(p, A, B):
    return moment_problem__C.from_dict({(i, 0, 0): v for (i, a, b), v in p.to_dict().items() if (a, b) == (A, B)})

def moment_problem__setup(out):
    _, red, _ = derive_a1__universal()
    euls = {g: moment_problem__euler(p) for g, p in red.items()}
    (out / 'euler_densities.json').write_text(moment_problem__json.dumps({g: [{'Q0_exponent_twice': ex, 'jet_powers': m, 'coefficient': str(v)} for (ex, m), v in p.items()] for g, p in euls.items()}, indent=2) + '\n')
    V = -moment_problem__X * moment_problem__w / 2 - moment_problem__Y * moment_problem__w * (1 - moment_problem__w) / 4 + (1 - moment_problem__w) / 16 - moment_problem__F(5, 16) * moment_problem__w * (1 - moment_problem__w)
    L = [moment_problem__C.constant(1)]
    Vs = [V]
    for j in range(6):
        L.append(moment_problem__D(L[-1]) + (moment_problem__F(3, 2) - moment_problem__F(5, 2) * moment_problem__w) * L[-1])
        Vs.append(moment_problem__D(Vs[-1]))
    expanded = []
    for g, p in euls.items():
        for (ex, m), v in p.items():
            pols = [moment_problem__C.constant(1)]
            for r, num in enumerate(m, 1):
                for _ in range(num):
                    np = [moment_problem__Z for _ in range(len(pols) + 1)]
                    for u, poly in enumerate(pols):
                        np[u] += poly * L[r]
                        np[u + 1] += poly * Vs[r]
                    pols = np
            expanded.append((g, moment_problem__F(ex, 2), moment_problem__F(str(v)), pols))
    return (V, expanded)

def moment_problem__poch(x, n):
    ans = moment_problem__F(1)
    if n >= 0:
        for j in range(n):
            ans *= x + j
    else:
        for j in range(1, 1 - n):
            ans /= x - j
    return ans

def moment_problem__beta_scale(s, ref):
    da, db = (-3 * (s - ref) // 4, -(s - ref) // 2)
    aa, bb = (moment_problem__F(-3 * ref, 4), moment_problem__F(-ref, 2))
    return moment_problem__poch(aa + bb, da + db) / (moment_problem__poch(aa, da) * moment_problem__poch(bb, db))

def moment_problem__normalizer(K):
    s = 2 * K - 1
    return moment_problem__binom(moment_problem__F(1, 2), K) * moment_problem__F(-1, 2) ** K * moment_problem__poch(moment_problem__F(-3 * s, 4), K) / moment_problem__poch(moment_problem__F(-5 * s, 4), K)

def moment_problem__kernel(K, out, V, expanded):
    P = moment_problem__Z
    powers = [moment_problem__C.constant(1)]
    for l in range(K):
        powers.append(powers[-1] * V)
    for g, p, v, pols in expanded:
        for u, pol in enumerate(pols):
            ell = K - g - u - 2
            if ell >= 0:
                P += v * moment_problem__binom(p, ell) * pol * powers[ell]
    top = moment_problem__normalizer(K)
    base = moment_problem__Z
    for drop in range(min(3, K) + 1):
        for A in range(K - drop + 1):
            B = K - drop - A
            val = check_a1__value(check_a1__coefficient(out, 1, K, A, drop), moment_problem__F(-1, 3))
            base += val * moment_problem__X ** A * moment_problem__Y ** B
    kernels = {}
    for kind, rs in moment_problem__KINDS.items():
        if rs is None:
            raw = moment_problem__F(1, 2) * moment_problem__binom(moment_problem__F(-1, 2), K - 3) * powers[K - 3] if K >= 3 else moment_problem__Z
        else:
            raw = P * moment_problem__X ** rs[0] * moment_problem__Y ** rs[1]
        raw = moment_problem__grade(raw, max(0, K - 3), K) / top
        top_response = moment_problem__spatial_coefficient(raw, K, 0)
        kernels[kind] = raw - top_response * base
    return kernels

def moment_problem__targets(K, out):
    result = {}
    for drop in range(min(3, K) + 1):
        for A in range(K - drop + 1):
            B = K - drop - A
            if drop < 2:
                val = moment_problem__F(0)
            else:
                n, d = map(check_a1__univariate, check_a1__coefficient(out, 1, K, A, drop, 'Delta_A1'))
                tv = moment_problem__F(-1, 3)
                val = (n.derivative()(tv) * d(tv) - n(tv) * d.derivative()(tv)) / d(tv) ** 2
            result[A, B] = val
    return result

def moment_problem__block(spins, kernels, targets_, maxdrop=3, relations=True, last_drop=None):
    sm = max(spins)
    ref = min(spins)
    rows = []
    mat = []
    rhs = []
    for s in spins:
        K = (s + 1) // 2
        limit = last_drop if last_drop is not None and s == sm else maxdrop
        for drop in range(min(K, limit) + 1):
            for A in range(K - drop + 1):
                B = K - drop - A
                if (A, B) == (K, 0):
                    continue
                vec = {}
                for kind in moment_problem__KINDS:
                    p = moment_problem__spatial_coefficient(kernels[kind, s], A, B) * moment_problem__beta_scale(s, ref) * moment_problem__w ** (3 * (sm - s) // 4) * (1 - moment_problem__w) ** ((sm - s) // 2)
                    for (i, _, __), v in p.to_dict().items():
                        vec[kind, i] = v
                rows.append((s, A, B))
                mat.append(vec)
                rhs.append(targets_[s][A, B])
    cols = sorted(set().union(*(v.keys() for v in mat)))
    arr = [[v.get(c, moment_problem__F(0)) for c in cols] for v in mat]
    A = moment_problem__fmpq_mat(arr)
    rank = A.rank()
    aug = moment_problem__fmpq_mat([r + [b] for r, b in zip(arr, rhs)]).rank()
    ans = {'spins': spins, 'drop_through': maxdrop, 'last_spin_drop_through': last_drop, 'rows': len(rows), 'columns': len(cols), 'rank': rank, 'augmented_rank': aug, 'relations': []}
    if relations and rank < len(rows):
        N = len(rows)
        RR, _ = moment_problem__fmpq_mat([r + [moment_problem__F(i == j) for j in range(N)] for i, r in enumerate(arr)]).rref()
        for i in range(N):
            if any((RR[i, j] for j in range(len(cols)))):
                continue
            v = [RR[i, len(cols) + j] for j in range(N)]
            residual = sum((x * y for x, y in zip(v, rhs)), moment_problem__F(0))
            if not residual:
                continue
            v = [x / residual for x in v]
            terms = [[str(x), *rows[j]] for j, x in enumerate(v) if x]
            for j in range(len(cols)):
                if sum((v[z] * arr[z][j] for z in range(N)), moment_problem__F(0)):
                    raise ArithmeticError('nonzero adjoint relation')
            ans['relations'].append({'terms': terms, 'target': '1'})
            break
    return ans

def moment_problem__run(out, smax=31):
    start = moment_problem__time.monotonic()
    V, expanded = moment_problem__setup(out)
    kernels = {}
    target = {}
    records = []
    crosschecks = []
    old = moment_problem__json.loads((out / 'source/adjoint_kernels.json').read_text())
    oldtarget = moment_problem__json.loads((out / 'source/class2_results.json').read_text())['targets']
    for s in range(3, smax + 1, 2):
        K = (s + 1) // 2
        kk = moment_problem__kernel(K, out, V, expanded)
        target[s] = moment_problem__targets(K, out)
        for kind, p in kk.items():
            kernels[kind, s] = p
            if f'{kind}:{s}' in old:
                diff = p - moment_problem__grade(moment_problem__decode(old[f'{kind}:{s}']), max(0, K - 3), K)
                if diff:
                    raise ArithmeticError(f'old-kernel hold-out mismatch {(kind, s)}: {diff}')
                crosschecks.append([kind, s])
        if str(s) in oldtarget:
            for (A, B), v in target[s].items():
                expected = oldtarget[str(s)].get(str((A, B)), '0')
                if v != moment_problem__F(expected):
                    raise ArithmeticError(f'target hold-out mismatch {(s, A, B, v, expected)}')
        spins = list(range(3 if s % 4 == 3 else 5, s + 1, 4))
        ans = moment_problem__block(spins, kernels, target, relations=False)
        records.append(ans)
        print('EXACT moment block', spins, 'rows', ans['rows'], 'rank', ans['rank'], 'augmented', ans['augmented_rank'], 'seconds', round(moment_problem__time.monotonic() - start, 2), flush=True)
        if ans['rank'] != ans['augmented_rank']:
            for drop in range(4):
                test = moment_problem__block(spins, kernels, target, maxdrop=drop, relations=True)
                if test['rank'] != test['augmented_rank']:
                    records.append(test)
                    print('EXACT FIRST OBSTRUCTION spin', s, 'drop', drop, 'relation terms', len(test['relations'][0]['terms']), flush=True)
                    break
            break
    (out / 'moment_kernels.json').write_text(moment_problem__json.dumps({f'{kind}:{s}': moment_problem__encode(p) for (kind, s), p in kernels.items()}, indent=2) + '\n')
    (out / 'moment_targets.json').write_text(moment_problem__json.dumps({s: {f'{A},{B}': str(v) for (A, B), v in p.items()} for s, p in target.items()}, indent=2) + '\n')
    result = {'status': 'EXACT', 'fit': 'none', 'blocks': records, 'kernel_holdouts': crosschecks, 'target_holdouts': list(oldtarget), 'scope': 'necessary tangent at Sol1 t=-1/3 for seven arbitrary functions; analytic scalar deformation vanishing at this exact point; four highest layers', 'exit': 2 if records[-1]['rank'] != records[-1]['augmented_rank'] else 3}
    (out / 'moment_results.json').write_text(moment_problem__json.dumps(result, indent=2) + '\n')
    return result['exit']

def moment_problem__first_layer_audit(out):
    kernels = {(kind, int(s)): moment_problem__decode(p) for key, p in moment_problem__json.loads((out / 'moment_kernels.json').read_text()).items() for kind, s in [key.split(':')]}
    target = {int(s): {tuple(map(int, key.split(','))): moment_problem__F(v) for key, v in p.items()} for s, p in moment_problem__json.loads((out / 'moment_targets.json').read_text()).items()}
    records = [moment_problem__block([3, 7, 11, 15], kernels, target, maxdrop=3, relations=False, last_drop=d) for d in range(4)]
    if any((r['rank'] != r['augmented_rank'] for r in records[:2])) or records[2]['rank'] == records[2]['augmented_rank']:
        raise ArithmeticError('first failing layer changed')
    (out / 'first_layer_check.json').write_text(moment_problem__json.dumps({'status': 'EXACT', 'blocks': records}, indent=2) + '\n')
    print('EXACT prior-spin constraints retained: spin15 top and sub-top consistent, degree6 first inconsistent.', flush=True)

# Original derivation unit: independent_check.py
"""Direct Riccati/linearized-Riccati check, independent of derivative grading."""
from pathlib import Path as independent_check__Path
import json as independent_check__json, sys as independent_check__sys, time as independent_check__time
from importlib.util import spec_from_file_location as independent_check__spec_from_file_location, module_from_spec as independent_check__module_from_spec
from flint import fmpq as independent_check__F

def independent_check__run(out, root):
    start = independent_check__time.monotonic()
    spec = independent_check__spec_from_file_location('old_assembly', root / 'lab/cyl_assembly_certificate.py')
    old = independent_check__module_from_spec(spec)
    spec.loader.exec_module(old)
    import sympy as S
    n, e, c, d = old.pars(1, old.t)
    t0 = S.Rational(-1, 3)

    def jet(expr):
        expr = S.sympify(expr)
        return (independent_check__F(str(expr.subs(old.t, t0))), independent_check__F(str(S.diff(expr, old.t).subs(old.t, t0))))
    nn, dn = jet(n)
    ee, de = jet(e)
    cc, dc = jet(c)
    dd, dd2 = jet(d)
    L = (-ee + nn * moment_problem__w) / 2
    dL = (-de + dn * moment_problem__w) / 2
    V = -cc * moment_problem__w * moment_problem__X / 2 + ((nn + 2) * moment_problem__Y / 2 + independent_check__F(1, 4) + dd) * moment_problem__w * (1 - moment_problem__w) - ee * (1 - moment_problem__w) / 24
    dV = -dc * moment_problem__w * moment_problem__X / 2 + (dn * moment_problem__Y / 2 + dd2) * moment_problem__w * (1 - moment_problem__w) - de * (1 - moment_problem__w) / 24
    R = [-L / 2]
    R1 = [-dL / 2]
    R.append((V - R[0] ** 2 - moment_problem__D(R[0])) / 2)
    R1.append((dV - 2 * R[0] * R1[0] - moment_problem__D(R1[0])) / 2)
    for j in range(1, 15):
        R.append(-(moment_problem__D(R[j]) - j * L * R[j] + sum((R[i] * R[j - i] for i in range(j + 1)), moment_problem__Z)) / 2)
        R1.append(-(moment_problem__D(R1[j]) - j * (dL * R[j] + L * R1[j]) + 2 * sum((R[i] * R1[j - i] for i in range(j + 1)), moment_problem__Z)) / 2)
    norm = {}
    top = {}
    jets = {}
    matches = 0
    tangent_matches = 0
    for s in range(3, 16, 2):
        aa, bb = (s * ee / 2, s * nn / 2)
        da, db = (s * de / 2, s * dn / 2)
        vals = {}
        dvals = {}
        for (i, A, B), v in R[s].to_dict().items():
            f = moment_problem__poch(aa, i) / moment_problem__poch(bb, i)
            df = f * sum((da / (aa + j) - db / (bb + j) for j in range(i)), independent_check__F(0))
            vals[0, A, B] = vals.get((0, A, B), independent_check__F(0)) + v * f
            dvals[0, A, B] = dvals.get((0, A, B), independent_check__F(0)) + v * df
        for (i, A, B), v in R1[s].to_dict().items():
            dvals[0, A, B] = dvals.get((0, A, B), independent_check__F(0)) + v * moment_problem__poch(aa, i) / moment_problem__poch(bb, i)
        K = (s + 1) // 2
        top[s] = vals[0, K, 0]
        norm[s] = moment_problem__C.from_dict(vals) / top[s]
        jets[s] = (moment_problem__C.from_dict(dvals) - norm[s] * dvals[0, K, 0]) / top[s]
        for drop in range(min(K, 3) + 1):
            for A in range(K - drop + 1):
                B = K - drop - A
                pair = check_a1__coefficient(out, 1, K, A, drop)
                v = check_a1__value(pair, independent_check__F(-1, 3))
                if v != norm[s].to_dict().get((0, A, B), independent_check__F(0)):
                    raise ArithmeticError('independent A1 value')
                N, DD = map(check_a1__univariate, pair)
                tv = independent_check__F(-1, 3)
                dv = (N.derivative()(tv) * DD(tv) - N(tv) * DD.derivative()(tv)) / DD(tv) ** 2
                if dv != jets[s].to_dict().get((0, A, B), independent_check__F(0)):
                    raise ArithmeticError('independent A1 derivative')
                matches += 1
                tangent_matches += 1

    def adjoints(start):
        js = [{} for _ in range(16)]
        js[start] = {0: moment_problem__C.constant(independent_check__F(1, 2))}
        for j in range(start, 15):
            acc = {r: moment_problem__D(v) - j * L * v for r, v in js[j].items()}
            for r, v in js[j].items():
                acc[r + 1] = acc.get(r + 1, moment_problem__Z) + v
            for m in range(j + 1):
                for r, v in js[j - m].items():
                    acc[r] = acc.get(r, moment_problem__Z) + 2 * R[m] * v
            js[j + 1] = {r: -v / 2 for r, v in acc.items() if v}
        ans = {}
        for s in norm:
            p = moment_problem__Z
            for r, v in js[s].items():
                for _ in range(r):
                    v = -moment_problem__D(v) + s * L * v
                p += v
            ans[s] = p
        return ans
    adj = {3: adjoints(3), 5: adjoints(5)}
    derived = independent_check__json.loads((out / 'moment_kernels.json').read_text())
    kernels = {}
    kernel_matches = 0
    for kind, rs in moment_problem__KINDS.items():
        for s in norm:
            K = (s + 1) // 2
            A, B = (0, 0) if rs is None else rs
            v = adj[5 if kind == 'U4' else 3][s] * moment_problem__X ** A * moment_problem__Y ** B
            kernels[kind, s] = (v - norm[s] * moment_problem__spatial_coefficient(v, K, 0)) / top[s]
            if moment_problem__grade(kernels[kind, s], max(0, K - 3), K) != moment_problem__decode(derived[f'{kind}:{s}']):
                raise ArithmeticError(f'independent kernel mismatch {(kind, s)}')
            kernel_matches += 1
    result = independent_check__json.loads((out / 'moment_results.json').read_text())
    terms = result['blocks'][-1]['relations'][0]['terms']

    def relation(kind, terms_):
        sm = max((r[1] for r in terms_))
        ref = min((r[1] for r in terms_))
        return sum((independent_check__F(c) * moment_problem__beta_scale(s, ref) * moment_problem__w ** (3 * (sm - s) // 4) * (1 - moment_problem__w) ** ((sm - s) // 2) * moment_problem__spatial_coefficient(kernels[kind, s], A, B) for c, s, A, B in terms_), moment_problem__Z)
    for kind in moment_problem__KINDS:
        if relation(kind, terms):
            raise ArithmeticError('independent relation fails')
        (out / f'relation_joint_{kind}.json').write_text(independent_check__json.dumps({'kind': kind, 'terms': terms}, indent=2) + '\n')
    independent_target = independent_check__F(0)
    for c, s, A, B in terms:
        K = (s + 1) // 2
        drop = K - A - B
        if drop < 2:
            continue
        N, DD = map(check_a1__univariate, check_a1__coefficient(out, 1, K, A, drop, 'Ward'))
        tv = independent_check__F(-1, 3)
        dw = (N.derivative()(tv) * DD(tv) - N(tv) * DD.derivative()(tv)) / DD(tv) ** 2
        independent_target += independent_check__F(c) * (dw - jets[s].to_dict().get((0, A, B), independent_check__F(0)))
